// ❌ OLD: Manual implementation of a Suspense resource cache throwing promises.
function createResource(promise) {
  let status = 'pending';
  let result;
  let suspender = promise.then(
    (r) => {
      status = 'success';
      result = r;
    },
    (e) => {
      status = 'error';
      result = e;
    }
  );

  return {
    read() {
      if (status === 'pending') throw suspender; // ❌ Throws Promise to Suspense
      if (status === 'error') throw result;      // Throws Error to ErrorBoundary
      if (status === 'success') return result;
    }
  };
}

// ✅ NEW: React 19's `use()` natively suspends without custom cache wrappers.
import { use, Suspense } from 'react';

function Profile({ userPromise }) {
  // use() throws the promise internally if pending, caught by Suspense:
  const user = use(userPromise);
  return <h2>{user.name}</h2>;
}

export default function App({ userPromise }) {
  return (
    <Suspense fallback={<div>Loading profile skeleton...</div>}>
      <Profile userPromise={userPromise} />
    </Suspense>
  );
}
